@namespace sv_d7270ea2256640db9168f74fb8aad5fc.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter</label>
        <textarea id="coverLetter" @bind="CoverLetterText" @bind:event="oninput"
                  class="form-control cover-letter-textarea"
                  maxlength="2000"
                  rows="12"></textarea>
        <span class="char-count @(CoverLetterText.Length > 1800 ? "char-count--warning" : "")">
            @CoverLetterText.Length / 2000 characters
        </span>
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetterText { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? _validationError;

    private async Task HandleNext()
    {
        _validationError = null;

        if (string.IsNullOrWhiteSpace(CoverLetterText))
        {
            _validationError = "Please write a cover letter.";
            return;
        }

        await OnNext.InvokeAsync(CoverLetterText);
    }
}

@namespace sv_d7270ea2256640db9168f74fb8aad5fc.Components.Pages.Apply

<div class="step-content">
    <h2>Review & Submit</h2>

    @if (_submitted)
    {
        <div class="submission-confirmation">
            <h3>&#10003; Application Submitted!</h3>
            <p>Your application has been received. Your application ID is <strong>@_applicationId</strong>.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="review-section__header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@PersonalFullName</dd>
                <dt>Email</dt><dd>@PersonalEmail</dd>
                <dt>Phone</dt><dd>@PersonalPhone</dd>
                <dt>Address</dt><dd>@PersonalAddress</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-section__header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @if (WorkEntries != null)
            {
                @foreach (var entry in WorkEntries)
                {
                    <div class="review-work-entry">
                        <strong>@entry.Title</strong> at @entry.Company
                        <br />
                        <span>@entry.StartDate.ToString("MMM yyyy") – @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</span>
                        <p>@entry.Description</p>
                    </div>
                }
            }
        </section>

        <section class="review-section">
            <div class="review-section__header">
                <h3>References</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @if (References != null)
            {
                @foreach (var r in References)
                {
                    <div class="review-reference">
                        <strong>@r.Name</strong> (@r.Relationship)
                        <br />@r.Email | @r.Phone
                    </div>
                }
            }
        </section>

        <section class="review-section">
            <div class="review-section__header">
                <h3>Cover Letter</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="review-cover-letter">@CoverLetter</p>
        </section>

        @if (!string.IsNullOrEmpty(_errorMessage))
        {
            <div class="validation-summary">@_errorMessage</div>
        }

        <div class="step-actions">
            <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
            <button class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@_isSubmitting">
                @if (_isSubmitting)
                {
                    <span>Submitting...</span>
                }
                else
                {
                    <span>Submit Application</span>
                }
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public string PersonalFullName { get; set; } = "";
    [Parameter] public string PersonalEmail { get; set; } = "";
    [Parameter] public string PersonalPhone { get; set; } = "";
    [Parameter] public string PersonalAddress { get; set; } = "";
    [Parameter] public List<WorkHistoryStep.WorkEntryState>? WorkEntries { get; set; }
    [Parameter] public List<ReferencesStep.ReferenceState>? References { get; set; }
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<int> OnEditSection { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public Func<Task<int>> SubmitApplication { get; set; } = default!;

    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;
    private string? _errorMessage;

    private async Task HandleSubmit()
    {
        _isSubmitting = true;
        _errorMessage = null;

        try
        {
            _applicationId = await SubmitApplication();
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}

