    color: white;
}

.step--completed .step__number {
    border-color: #198754;
    background: #198754;
    color: white;
}

.step--future .step__number {
    opacity: 0.5;
}

.step__check {
    font-size: 1rem;
}

.step__label {
    font-size: 0.75rem;
    color: #666;
    text-align: center;
}

.step--current .step__label {
    color: #0d6efd;
    font-weight: 600;
}

.step--completed .step__label {
    color: #198754;
}

.step--future .step__label {
    opacity: 0.5;
}

.step__connector {
    flex: 0 0 2rem;
    height: 2px;
    background: #ccc;
    align-self: center;
    margin-bottom: 1.25rem;
}

.step__connector--completed {
    background: #198754;
}

/* Step Content */
.step-content {
    background: white;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #333;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
    color: #444;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.15);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.field-error {
    color: #dc3545;
    font-size: 0.875rem;
    margin-top: 0.25rem;
    display: block;
}

