+@page "/apply"
+@using sv_d7270ea2256640db9168f74fb8aad5fc.Components.Pages.Apply
+@using sv_d7270ea2256640db9168f74fb8aad5fc.Models
+@rendermode InteractiveServer
+@inject IApplicationService ApplicationService
+
+<PageTitle>Job Application</PageTitle>
+
+<div class="application-form">
+    <h1>Job Application</h1>
+
+    <StepIndicator CurrentStep="_currentStep"
+                   CompletedSteps="_completedSteps"
+                   OnStepClicked="GoToStep" />
+
+    @switch (_currentStep)
+    {
+        case 0:
+            <PersonalInfoStep FullName="@_fullName"
+                              Email="@_email"
+                              Phone="@_phone"
+                              Address="@_address"
+                              ValidateEmail="ApplicationService.ValidateEmailAsync"
+                              OnNext="HandlePersonalInfoNext" />
+            break;
+
+        case 1:
+            <WorkHistoryStep InitialEntries="_workEntries"
+                             OnNext="HandleWorkHistoryNext"
+                             OnBack="GoBack" />
+            break;
+
+        case 2:
+            <ReferencesStep InitialReferences="_references"
+                            OnNext="HandleReferencesNext"
+                            OnBack="GoBack" />
+            break;
+
+        case 3:
+            <CoverLetterStep CoverLetterText="@_coverLetter"
+                             OnNext="HandleCoverLetterNext"
+                             OnBack="GoBack" />
+            break;
+
+        case 4:
+            <ReviewStep PersonalFullName="@_fullName"
+                        PersonalEmail="@_email"
+                        PersonalPhone="@_phone"
+                        PersonalAddress="@_address"
+                        WorkEntries="_workEntries"
+                        References="_references"
+                        CoverLetter="@_coverLetter"
+                        OnEditSection="GoToStep"
+                        OnBack="GoBack"
+                        SubmitApplication="SubmitApplication" />
+            break;
+    }
+</div>
+
+@code {
+    private int _currentStep;
+    private readonly HashSet<int> _completedSteps = new();
+
+    // Step 1 state
+    private string _fullName = "";
+    private string _email = "";
+    private string _phone = "";
+    private string _address = "";
